def parse_price(s: str) -> float | None:
    if not isinstance(s, str):
        return None
    s = s.replace('\xa0', ' ').strip()
    if not s:
        return None
    cleaned = ''.join(ch for ch in s if ch != '€' and ch != ' ')
    if not cleaned:
        return None
    if cleaned.lower().startswith('gratis'):
        return 0.0
    if any(ch not in '0123456789.,-' for ch in cleaned):
        return None
    cleaned = cleaned.replace('.', '')
    if ',' in cleaned:
        int_part, _, dec_part = cleaned.partition(',')
        dec_part = dec_part.replace('-', '')
        if not int_part.isdigit():
            return None
        if not dec_part:
            dec_part = '0'
        if not dec_part.isdigit():
            return None
        return float(int_part + '.' + dec_part)
    if cleaned.isdigit():
        return float(cleaned)
    return None

