import re

def is_valid_postcode(s: str) -> bool:
    if not isinstance(s, str):
        return False
    m = re.fullmatch(r'([1-9][0-9]{3})( )?([A-Za-z]{2})', s)
    if m is None:
        return False
    letters = m.group(2).upper()
    return letters not in {'SA', 'SD', 'SS'}

