def next_pickup_slot(now: datetime.datetime) -> datetime.datetime:
    current_date = now.date()
    while True:
        weekday = current_date.weekday()
        if weekday <= 4:
            window_start = datetime.time(18, 0)
            window_end = datetime.time(21, 0)
        elif weekday == 5:
            window_start = datetime.time(10, 0)
            window_end = datetime.time(16, 0)
        else:
            current_date += datetime.timedelta(days=1)
            continue

        slot = datetime.datetime.combine(current_date, window_start)
        end = datetime.datetime.combine(current_date, window_end)
        while slot < end:
            if slot >= now:
                return slot
            slot += datetime.timedelta(minutes=30)

        current_date += datetime.timedelta(days=1)

