def dedupe(listings: list[dict]) -> list[dict]:
    def normalize_title(title: str) -> str:
        return ' '.join(title.split()).lower()

    best = {}  # key -> index of the earliest-dated item
    for i, item in enumerate(listings):
        key = (normalize_title(item['title']), item['price'])
        j = best.get(key)
        if j is None or item['date'] < listings[j]['date']:
            best[key] = i

    return [listings[i] for i in sorted(best.values())]

